import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"42、【益】 震下巽上","description":"周易集注 - 42、【益】 震下巽上","frontmatter":{"title":"42、【益】 震下巽上","description":"周易集注 - 42、【益】 震下巽上"},"headers":[],"relativePath":"zh/classics/jizhu/046.md","filePath":"zh/classics/jizhu/046.md"}'),r={name:"zh/classics/jizhu/046.md"};function i(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_42、【益】-震下巽上" tabindex="-1">42、【益】 震下巽上 <a class="header-anchor" href="#_42、【益】-震下巽上" aria-label="Permalink to “42、【益】 震下巽上”">​</a></h1><p>益与损相综，益之震上而为艮，则损下以益上，所以名损;损之艮下而为震，则损上以益下，所以名益。《序卦》：损而不已必益，故受之以益，所以次损。</p><p>利有攸往者，凡事无不利也。利涉大川者，言不惟利所往，可以处常，亦可以济变。</p><p>彖曰：益，损上益下，民说无疆，自上下下，其道大光。利有攸往，中正有庆;利涉大川，木道乃行。益动而巽，日进无疆，天施地生，其益无方，凡益之道，与时偕行。</p><p>以卦综释卦名，以卦体卦象卦德释卦辞，而赞之。损，损上卦之艮;益，益下卦而为震也。民说无疆，就损益所及之泽而言也，益在民也。其道大光，就损益所行之事而言也，益在君也。人君居九重之上，而能膏泽及于闾阎之民，则其道与乾坤同其广大，与日月同其光明。何大光如之?卦本损上，然能损上以益下，则并上亦益矣。民益君，益所以名益。九五以中正位乎上，而六二以中正应之，是圣主得贤臣而庆，泽自流于天下矣，所以利有攸往也。木道乃行者，亦如中孚之舟虚，乃风中之木，故木道乃行。中孚、涣皆风木，且本卦象离错坎，亦有水象。动而巽者，动则有奋发之勇而不柔弱，巽则有顺入之渐而不卤莽，所以德崇业广。日进无疆，此以卦德言也。震乃刚卦，为天，天施者初之阳也，巽乃柔卦，为地，地生者四之阴也。天以一阳施于下，则天道下济而资其始也，以一阴升于上，则地道上行而资其生，所以品物咸亨。而其益无方，此以卦题言也。时者理之当其可也，言凡益之道，非理之本无而勉强增益之也，乃理之当其可而后增益也，如曰日进无疆者，以人事当然之理而益也。曰其益无方者，以造化自然之理而益也，理之所在，当益而益，是以自我益之。改过迁善，不嫌其多，自人益之，十朋之龟愈见其吉矣。</p><p>象曰：风雷，益，君子以见善则迁，有过则改。</p><p>风雷之势，交相助益，益之道也。善者天理也，吾性之本有也。过者人欲也，吾性之本无也。理欲相为乘除，去得一分人欲，则存得一分天理。人有善而迁从，则过益寡;已有过而速改，则善益增，即风雷之交相助，益矣。</p><p>初九，利用为大作，元吉，无咎。</p><p>大作者，厚事也，如迁国大事之类是也，故曰益以兴利。阳大阴小，此爻阳，故以大言之。元吉，以功言，非诸爻以效言也。</p><p>初刚在下，为动之主，当益之时，受上之益者也。六四近君，与初为正应，而为六四所信任，以其有刚明之才，故占者利用为大作。然位卑任重，则有所不堪者，必其所作之事周悉万全，为经久之良图，至于元善，方可无咎。茍轻用败事，必负六四之信任矣，故戒占者以此。</p><p>象曰：元吉，无咎，下不厚事也。</p><p>下者，下位也。厚事者，大作也。初位卑，本不可以任厚事，岂能无咎，故必大善而后无咎也。</p><p>六二，或益之，十朋之龟，弗克违，永贞吉。王用享于帝，吉。</p><p>损之六五即益之六二，以其相综，特倒转耳，故其象同。损受下之益，此则受上之益。十朋之龟者，宠锡优渥之象也。永贞吉者，必长永贞，固守其虚中之德，而后可以常保其优渥之宠锡也。王用亨于帝者，言永贞虚中之心，必如人君之对越在天，小心翼翼也，此一句又永贞之象，乃占中之象也。帝出震，齐巽，本卦下震上巽，帝之象也。</p><p>六二当益之时，虚中处下，盖精白一心一事君，本无求益之心而自得君之宠益者也，故有或益十朋之龟弗克违之象。然爻位皆阴，又戒以永贞，必事君如事天，而后可以受此益也，故又有王用享于帝之象，占者必如是方吉也。</p><p>象曰：或益之，自外来也。</p><p>言不知所从来也，与上九自外来同。二则吉来，上则凶来。</p><p>六三，益之，用凶事，无咎。有孚，中行告公，用圭。</p><p>凶者，险阻盘错也，如使大将出师，及使至海外之国，岂不是凶。三之爻位本凶，说文云：凶象地穿交陷其中。中爻坤地震极，未有不陷者，凶之象也。无咎者，凶事乃上之所益，三不得与焉，所以无咎也。有孚者，诚信也。中行者，中道可行之事也。凶事乃太过之事，故以中言之。告公者，告于四也。故六四曰：中行告公从。圭乃通信之物，祭祀朝聘用之，所以达诚信也。六爻中虚，有孚之象也，巽综兑，兑为口，告之象也，故夬外卦兑亦曰告自邑，泰卦中爻兑亦曰自邑告命，震为玉圭之象也，用圭乃有孚之象，又占中之象也。有孚以下，乃圣人教占者开凶事之路也。</p><p>六三阴柔不中不正，又居益下之极，当益下之时，故有受上之益而用行凶事之象，占者得此可以无咎，若以阴柔不堪此凶事，必当有孚诚信，以中道可行之事告于公，如用圭通诚信焉，庶乎凶事或可免也。故又有中行告公用圭之象，教占者必如此。</p><p>象曰：益用凶事，固有之也。</p><p>固有之者，本有之也。言三之爻位多凶，则凶事乃三之本有也。孔子三多凶之句，本原于周公之爻辞，六十四卦惟谦卦三爻有吉字，馀皆无，故三多凶。</p><p>六四，中行，告公从，利用为依迁国。</p><p>中行告公者，即三爻以中道可行之事而告于四也。从者，巽性顺，从之象也。为字去声。凡迁国安民，必为其依而后迁。依者，依其形胜也，依形胜即所以依民也，如汉高祖之徙长安，以其地阻，三面可守，独以一面东制诸侯，依其险而迁者也。国有所依，则不费其兵，不费其财，而民有所依矣。宋太阻亦欲徙长安，因晋王固谏，乃叹曰：不出百年，天下民力殚矣，以四面受敌，无所依也。故周公不曰“利用迁国”，而曰“为依迁国”。中爻坤，国之象也。损益相综，损卦艮之一阳下而迁为益之初，兑三之阴上而迁为益之四，迁之象也。九五坐于上而三阴两列中空，如天府，前后一阳，为之藩屏，有所凭依，一统之象也，故利用为依迁国，盖迁国安民，乃益下中行之大事，则非凶事矣，故三告而四从也。</p><p>四阴得正，有益下之志，而又有益下之权者也，三乃受四之益者。若以中道可行之事，告于四而四从之，上下协谋则利用为依迁国而凡事之可迁移者，亦无不利也，故其象如此，占可知矣。</p><p>象曰：告公从，以益志也。</p><p>八卦正位，巽在四，四以益下为志，故告公从。</p><p>九五，有孚，惠心，勿问元吉。有孚，惠我德。</p><p>惠者，即益下之惠也。心者，益下之心也。德者，益下之政也。二、三皆受上之益者也，则益之权在四矣。三比四，有孚于四，以中行告四，四从之。五比四，有孚于四，四不必告五，五亦不必问四矣。下于上曰告，上于下曰问。盖正位在四，知其必能惠下也，所以勿问也，故小象曰：勿问之矣。巽为命，综兑为口，中爻坤，错干为言，皆告问之象也，故三爻、四爻、五爻，曰告曰问，五爻变成艮矣，艮止，勿问之象也。我者五，自谓也。元吉，即有孚惠德也。言四之惠者，皆五之德也。</p><p>九五阳德中正，为益下之主，当益之时，以益下之惠心，有孚于四，不必问而知其元吉矣，何也?盖五孚于四五之心，知四必能惠我之德也，故有勿问之象，而占者元吉。</p><p>象曰：有孚惠心，勿问之矣;惠我德，大得志也。</p><p>四之小象曰告公从，五曰勿问之矣。见告问二字，为重上下相联属也。四曰以益者也，五曰大得志也，见四以益下为志，而此则大得益下之志也。看六爻要留心小象。</p><p>上九，莫益之，或击之，立心勿恒，凶。</p><p>莫益者，莫能益也。此爻与恒卦九三同，亦不恒其德者也。所以下句言勿恒，盖巽为进退不果，勿恒之象也，所以莫益也。又变坎为盗，中爻艮为手，大象离为戈兵，坎错离亦为戈兵，盗贼手持戈兵，击之象也。此与蒙卦上九击字相同，通是有此象，前儒不识象，止以理度之，就说求益不已，放于利而行多怨，不夺不餍，往往似此失易之旨，殊不知益卦不比损卦，损刚益柔有时，非恒常之道也，若益而不已，则日进无疆，其益无方，所以立心当恒，若不恒，不能益而不已，则凶矣。</p><p>上九以阳刚居益之极，极则变而不益矣，故有莫益或击之象，所以然者，以其立心不恒也，若益民之心，恒久不变，则民说无疆矣，安有击之之凶哉，惟其立心不恒，所以占者凶。</p><p>象曰：莫益之，偏辞也;或击之，自外来也。</p><p>辞者爻辞也，偏对正言，言非爻辞之正意也。正意在下句，言且莫言，莫能益也，此非到底之辞，犹有击之之者，此是正辞也。自外来，与六二同，但分吉凶耳。</p>',37)])])}const m=a(r,[["render",i]]);export{h as __pageData,m as default};
